-- Filename generated by Supabase CLI 2.121.0 `migration new account_integration`.
-- No live project settings, credentials, Auth users, or Owner grants are changed here.
begin;

create schema app_private;
revoke all on schema app_private from public, anon, authenticated;
grant usage on schema app_private to authenticated;

create table app_private.counters (
  name text primary key,
  number bigint not null default 0 check (number between 0 and 9007199254740991)
);
insert into app_private.counters (name) values ('users');

create table app_private.published_spell_ids (spell_id text primary key);
insert into app_private.published_spell_ids (spell_id) values
  ('Spell_1_Lumos_2026-10-06_719dd0e1-506a-4e67-9b02-04d4af1b4931'),
  ('Spell_2_Fus-Ro-Dah_2026-10-06_719dd0e2-506a-4e67-9b02-04d4af1b4932'),
  ('Spell_3_Brisingr_2026-10-06_719dd0e3-506a-4e67-9b02-04d4af1b4933'),
  ('Spell_4_Alohomora_2026-10-06_719dd0e4-506a-4e67-9b02-04d4af1b4934'),
  ('Spell_5_Wingardium-Leviosa_2026-10-06_719dd0e5-506a-4e67-9b02-04d4af1b4935'),
  ('Spell_6_Expelliarmus_2026-10-06_719dd0e6-506a-4e67-9b02-04d4af1b4936'),
  ('Spell_7_Expecto-Patronum_2026-10-06_719dd0e7-506a-4e67-9b02-04d4af1b4937'),
  ('Spell_8_Adurna_2026-10-06_719dd0e8-506a-4e67-9b02-04d4af1b4938'),
  ('Spell_9_Jierda_2026-10-06_719dd0e9-506a-4e67-9b02-04d4af1b4939');

create table public.accounts (
  id text primary key,
  number bigint not null unique check (number between 1 and 9007199254740991),
  auth_uid uuid not null unique references auth.users (id) on delete restrict,
  email text not null check (char_length(email) between 1 and 320),
  role text not null default 'Subscriber' check (role in ('Owner', 'Admin', 'Developer', 'Subscriber', 'Member')),
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint accounts_app_id check (
    id ~ ('^User_' || number::text || '_Account_[0-9]{4}-[0-9]{2}-[0-9]{2}_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
  )
);

create table public.profiles (
  account_id text primary key references public.accounts (id) on delete restrict,
  display_name text not null default 'Archivist' check (
    char_length(display_name) between 1 and 80
    and display_name = btrim(display_name)
    and display_name !~ '[[:cntrl:]]'
  ),
  avatar_url text check (
    avatar_url is null or (
      char_length(avatar_url) <= 2048
      and avatar_url ~ '^https://[^/?#@[:space:]]+([/?#][^[:space:]]*)?$'
      and avatar_url !~ '[[:cntrl:]]'
    )
  ),
  privacy text not null default 'private' check (privacy = 'private'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.saved_spells (
  account_id text not null references public.accounts (id) on delete restrict,
  spell_id text not null references app_private.published_spell_ids (spell_id) on delete restrict,
  is_saved boolean not null default true,
  saved_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  revision bigint not null default 1 check (revision between 1 and 9007199254740991),
  primary key (account_id, spell_id)
);
create index saved_spells_active_account_idx on public.saved_spells (account_id, spell_id) where is_saved;

create table app_private.role_change_audit (
  id bigint generated always as identity primary key,
  actor_auth_uid uuid,
  target_auth_uid uuid not null,
  previous_role text not null,
  next_role text not null,
  previous_active boolean not null,
  next_active boolean not null,
  reason text not null check (char_length(reason) between 1 and 500),
  created_at timestamptz not null default now()
);

alter table public.accounts enable row level security;
alter table public.profiles enable row level security;
alter table public.saved_spells enable row level security;
alter table app_private.counters enable row level security;
alter table app_private.published_spell_ids enable row level security;
alter table app_private.role_change_audit enable row level security;

-- Authorization helpers are deliberately outside exposed schemas. Each derives the actor
-- from auth.uid(); neither editable metadata nor browser-supplied IDs grant authority.
create function app_private.own_account_id()
returns text language sql stable security definer set search_path = ''
as $$
  select a.id from public.accounts a
  where auth.uid() is not null and a.auth_uid = auth.uid();
$$;

create function app_private.active_account_id()
returns text language sql stable security definer set search_path = ''
as $$
  select a.id from public.accounts a
  where auth.uid() is not null and a.auth_uid = auth.uid() and a.active;
$$;

create function app_private.is_owner()
returns boolean language sql stable security definer set search_path = ''
as $$
  select auth.uid() is not null and exists (
    select 1
    from public.accounts a
    join auth.users u on u.id = a.auth_uid
    join auth.sessions s on s.user_id = u.id
    where a.auth_uid = auth.uid() and a.active and a.role = 'Owner'
      and u.email_confirmed_at is not null and not coalesce(u.is_anonymous, false)
      and s.id::text = auth.jwt() ->> 'session_id'
  );
$$;

create policy accounts_read_self_or_owner on public.accounts for select to authenticated
using (auth_uid = (select auth.uid()) or (select app_private.is_owner()));

create policy profiles_read_self_or_owner on public.profiles for select to authenticated
using (account_id = (select app_private.own_account_id()) or (select app_private.is_owner()));

create policy profiles_update_self on public.profiles for update to authenticated
using (account_id = (select app_private.active_account_id()))
with check (account_id = (select app_private.active_account_id()));

create policy saved_spells_read_self on public.saved_spells for select to authenticated
using (account_id = (select app_private.active_account_id()));

create function app_private.touch_updated_at()
returns trigger language plpgsql security invoker set search_path = ''
as $$
begin
  new.updated_at := clock_timestamp();
  return new;
end;
$$;
create trigger profiles_updated_at before update on public.profiles
for each row execute function app_private.touch_updated_at();
create trigger accounts_updated_at before update on public.accounts
for each row execute function app_private.touch_updated_at();

create function app_private.ensure_account(p_expected_auth_uid uuid)
returns setof public.accounts language plpgsql security definer set search_path = ''
as $$
declare
  actor uuid := auth.uid();
  identity auth.users%rowtype;
  account public.accounts%rowtype;
  next_number bigint;
  initial_name text;
  initial_avatar text;
begin
  if actor is null or p_expected_auth_uid is distinct from actor then raise exception 'Sign in to connect your account.' using errcode = '42501'; end if;
  select * into identity from auth.users where id = actor;
  if not found or coalesce(identity.is_anonymous, false) or nullif(identity.email, '') is null then
    raise exception 'A permanent email account is required.' using errcode = '42501';
  end if;
  -- Serialize first-session callbacks without trusting a browser-generated account mapping.
  perform pg_advisory_xact_lock(hashtextextended(actor::text, 0));
  select * into account from public.accounts where auth_uid = actor;
  if found then
    if account.email is distinct from identity.email then
      update public.accounts set email = identity.email where id = account.id returning * into account;
    end if;
    return next account;
    return;
  end if;

  update app_private.counters set number = number + 1 where name = 'users' returning number into next_number;
  if next_number is null then raise exception 'Account allocation is unavailable.'; end if;
  insert into public.accounts (id, number, auth_uid, email)
  values (
    'User_' || next_number::text || '_Account_' || to_char(now() at time zone 'UTC', 'YYYY-MM-DD') || '_' || gen_random_uuid()::text,
    next_number, actor, identity.email
  ) returning * into account;

  -- Provider metadata initializes display fields only; it cannot affect roles or status.
  initial_name := nullif(btrim(left(regexp_replace(coalesce(
    nullif(identity.raw_user_meta_data ->> 'display_name', ''),
    nullif(identity.raw_user_meta_data ->> 'full_name', ''),
    nullif(identity.raw_user_meta_data ->> 'name', ''), 'Archivist'
  ), '[[:cntrl:]]', '', 'g'), 80)), '');
  initial_avatar := nullif(btrim(identity.raw_user_meta_data ->> 'avatar_url'), '');
  if initial_avatar is not null and (
    char_length(initial_avatar) > 2048
    or initial_avatar !~ '^https://[^/?#@[:space:]]+([/?#][^[:space:]]*)?$'
    or initial_avatar ~ '[[:cntrl:]]'
  ) then initial_avatar := null; end if;
  insert into public.profiles (account_id, display_name, avatar_url)
  values (account.id, coalesce(initial_name, 'Archivist'), initial_avatar);
  return next account;
end;
$$;

-- One account row lock serializes all favorites operations, limit checks and bulk actions.
create function app_private.lock_active_account(p_expected_auth_uid uuid)
returns text language plpgsql security definer set search_path = ''
as $$
declare account_id text;
begin
  if auth.uid() is null or p_expected_auth_uid is distinct from auth.uid() then raise exception 'Sign in to save spells.' using errcode = '42501'; end if;
  select a.id into account_id from public.accounts a
  where a.auth_uid = auth.uid() and a.active for update;
  if account_id is null then raise exception 'Your active account could not be confirmed.' using errcode = '42501'; end if;
  return account_id;
end;
$$;

create function app_private.set_saved_spell(p_spell_id text, p_is_saved boolean, p_expected_auth_uid uuid)
returns void language plpgsql security definer set search_path = ''
as $$
declare
  actor_account_id text := app_private.lock_active_account(p_expected_auth_uid);
  existing public.saved_spells%rowtype;
begin
  if p_is_saved is null or not exists (select 1 from app_private.published_spell_ids where spell_id = p_spell_id) then
    raise exception 'Only a spell in the current published archive can be saved.' using errcode = '22023';
  end if;
  select * into existing from public.saved_spells where account_id = actor_account_id and spell_id = p_spell_id;
  if found and existing.is_saved = p_is_saved then return; end if;
  if p_is_saved and (select count(*) from public.saved_spells where account_id = actor_account_id and is_saved) >= 500 then
    raise exception 'Save at most 500 spells per account.' using errcode = '22023';
  end if;
  if not p_is_saved then
    update public.saved_spells set is_saved = false, revision = revision + 1, updated_at = clock_timestamp()
    where account_id = actor_account_id and spell_id = p_spell_id and is_saved;
  else
    insert into public.saved_spells (account_id, spell_id) values (actor_account_id, p_spell_id)
    on conflict (account_id, spell_id) do update
    set is_saved = true, saved_at = clock_timestamp(), updated_at = clock_timestamp(), revision = public.saved_spells.revision + 1;
  end if;
end;
$$;

create function app_private.import_saved_spells(p_spell_ids text[], p_expected_auth_uid uuid)
returns void language plpgsql security definer set search_path = ''
as $$
declare actor_account_id text := app_private.lock_active_account(p_expected_auth_uid);
begin
  if p_spell_ids is null or cardinality(p_spell_ids) > 500 or coalesce(array_ndims(p_spell_ids), 1) <> 1 then
    raise exception 'Import at most 500 spell references at a time.' using errcode = '22023';
  end if;
  if exists (
    select 1 from unnest(p_spell_ids) requested(spell_id)
    left join app_private.published_spell_ids eligible using (spell_id) where eligible.spell_id is null
  ) then raise exception 'The import contains an unpublished spell.' using errcode = '22023'; end if;
  if (
    select count(*) from (
      select spell_id from public.saved_spells where account_id = actor_account_id and is_saved
      union select unnest(p_spell_ids)
    ) combined
  ) > 500 then raise exception 'The combined collection exceeds 500 saved spells.' using errcode = '22023'; end if;

  insert into public.saved_spells (account_id, spell_id)
  select actor_account_id, spell_id from (select distinct unnest(p_spell_ids) as spell_id) requested
  on conflict (account_id, spell_id) do update
  set is_saved = true, saved_at = clock_timestamp(), updated_at = clock_timestamp(), revision = public.saved_spells.revision + 1
  where not public.saved_spells.is_saved;
end;
$$;

create function app_private.clear_saved_spells(p_expected jsonb, p_expected_auth_uid uuid)
returns void language plpgsql security definer set search_path = ''
as $$
declare
  actor_account_id text := app_private.lock_active_account(p_expected_auth_uid);
  expected_count integer;
begin
  if p_expected is null or jsonb_typeof(p_expected) <> 'array' then
    raise exception 'Refresh your saved spells before clearing them.' using errcode = '22023';
  end if;
  expected_count := jsonb_array_length(p_expected);
  if expected_count > 500 then raise exception 'Clear at most 500 saved spells at a time.' using errcode = '22023'; end if;
  if exists (
    select 1 from jsonb_array_elements(p_expected) entry
    where jsonb_typeof(entry) <> 'object'
      or not (entry ? 'spell_id' and entry ? 'revision')
      or entry - 'spell_id' - 'revision' <> '{}'::jsonb
      or jsonb_typeof(entry -> 'spell_id') <> 'string'
      or jsonb_typeof(entry -> 'revision') <> 'number'
      or (entry ->> 'revision') !~ '^[1-9][0-9]{0,15}$'
  ) then raise exception 'The saved-spell snapshot is invalid.' using errcode = '22023'; end if;

  if (select count(distinct entry ->> 'spell_id') from jsonb_array_elements(p_expected) entry) <> expected_count
    or (select count(*) from public.saved_spells where account_id = actor_account_id and is_saved) <> expected_count
    or exists (
      select 1 from jsonb_to_recordset(p_expected) expected(spell_id text, revision bigint)
      left join public.saved_spells actual
        on actual.account_id = actor_account_id and actual.spell_id = expected.spell_id
        and actual.is_saved and actual.revision = expected.revision
      where actual.spell_id is null
    ) then
    raise exception 'Your saved spells changed on another device. Refresh before clearing them.' using errcode = '40001';
  end if;
  update public.saved_spells set is_saved = false, revision = revision + 1, updated_at = clock_timestamp()
  where account_id = actor_account_id and is_saved;
end;
$$;

-- Public RPC wrappers execute as the caller. Privileged implementations remain unexposed,
-- fixed-search-path functions with explicit actor checks and narrowly granted execution.
create function public.ensure_account(p_expected_auth_uid uuid)
returns setof public.accounts language sql security invoker set search_path = ''
as $$ select * from app_private.ensure_account(p_expected_auth_uid); $$;
create function public.set_saved_spell(p_spell_id text, p_is_saved boolean, p_expected_auth_uid uuid)
returns void language sql security invoker set search_path = ''
as $$ select app_private.set_saved_spell(p_spell_id, p_is_saved, p_expected_auth_uid); $$;
create function public.import_saved_spells(p_spell_ids text[], p_expected_auth_uid uuid)
returns void language sql security invoker set search_path = ''
as $$ select app_private.import_saved_spells(p_spell_ids, p_expected_auth_uid); $$;
create function public.clear_saved_spells(p_expected jsonb, p_expected_auth_uid uuid)
returns void language sql security invoker set search_path = ''
as $$ select app_private.clear_saved_spells(p_expected, p_expected_auth_uid); $$;

revoke all on all tables in schema app_private from public, anon, authenticated;
revoke all on all sequences in schema app_private from public, anon, authenticated;
revoke all on all functions in schema app_private from public, anon, authenticated;
revoke all on public.accounts, public.profiles, public.saved_spells from public, anon, authenticated;
revoke all on function public.ensure_account(uuid) from public, anon, authenticated;
revoke all on function public.set_saved_spell(text, boolean, uuid) from public, anon, authenticated;
revoke all on function public.import_saved_spells(text[], uuid) from public, anon, authenticated;
revoke all on function public.clear_saved_spells(jsonb, uuid) from public, anon, authenticated;

grant usage on schema public to authenticated;
grant select on public.accounts, public.profiles, public.saved_spells to authenticated;
grant update (display_name, avatar_url) on public.profiles to authenticated;
grant execute on function app_private.own_account_id(), app_private.active_account_id(), app_private.is_owner() to authenticated;
grant execute on function app_private.ensure_account(uuid) to authenticated;
grant execute on function app_private.set_saved_spell(text, boolean, uuid), app_private.import_saved_spells(text[], uuid), app_private.clear_saved_spells(jsonb, uuid) to authenticated;
grant execute on function public.ensure_account(uuid), public.set_saved_spell(text, boolean, uuid), public.import_saved_spells(text[], uuid), public.clear_saved_spells(jsonb, uuid) to authenticated;

-- No hard deletes are available to clients. Removing a favorite writes a private UPDATE
-- tombstone, avoiding unfilterable DELETE events and preserving concurrency revisions.
do $$
declare table_name text;
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    raise exception 'The Supabase Realtime publication is missing; confirm project configuration before applying.';
  end if;
  foreach table_name in array array['accounts', 'profiles', 'saved_spells'] loop
    if not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = table_name
    ) then execute format('alter publication supabase_realtime add table public.%I', table_name); end if;
  end loop;
end;
$$;

comment on table public.accounts is 'Private authoritative app accounts. Browser role/status/identity writes are denied.';
comment on table public.profiles is 'Private allowlisted display details; no public sharing is enabled.';
comment on table public.saved_spells is 'Own-account favorites; normal removal is a revisioned tombstone, never a DELETE.';
comment on schema app_private is 'Internal implementation; do not add to exposed Data API schemas.';
commit;
